import{H as e,gt as t,nt as n,tt as r}from"./chunks/framework.sms2Rnvf.js";var i=JSON.parse(`{"title":"User enumeration","description":"","frontmatter":{"search":{"exclude":true}},"headers":[],"relativePath":"d/web/user-enumeration.md","filePath":"d/web/user-enumeration.md","lastUpdated":1781102819000}`),a={name:`d/web/user-enumeration.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /d/web/user-enumeration.md for this page in Markdown format</div><h1 id="user-enumeration" tabindex="-1">User enumeration <a class="header-anchor" href="#user-enumeration" aria-label="Permalink to “User enumeration”">​</a></h1><h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to “Description”">​</a></h2><p>Web applications sometimes indicate whether a username or e-mail address exists as a user. Two of the most common places this occurs are the web application&#39;s login page or the &quot;forgot password&quot; functionality. For example, users who enter incorrect credentials receive the information that their password was wrong. An attacker can now use the information to determine whether a particular username exists. An attacker can now use the data to specify a list of valid usernames.</p><p>Once attackers have such a list, they can address these user accounts in new attacks to obtain valid credentials. In its simplest form, an attacker could perform password-guessing attacks. Attackers can use large word lists containing frequently used passwords for this. An attacker could also use enumerated usernames to search past data leaks for passwords. Credentials from data leaks, consisting of pairs of usernames and passwords, can be reused by attackers in automated attacks. This particular form of brute force attack is also known as credential stuffing. Alternatively, an attacker can use usernames during social engineering campaigns to contact users.</p><h2 id="recommendation" tabindex="-1">Recommendation <a class="header-anchor" href="#recommendation" aria-label="Permalink to “Recommendation”">​</a></h2><ul><li>Ensure the web application returns generic error messages when users enter invalid credentials.</li><li>Ensure that web server response times are similar for valid and invalid user accounts.</li></ul>`,7)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};